// Work Items Adapter Types
export interface ItemsCreateItemArgs {
  title: string; // Imperative, specific title in plain language (max 200 chars), e.g. "Add retry logic to auth refresh" — renders on teammates' home feeds, so no commit-message prefixes, hashes, or jargon
  source?: string; // Where this was decided — a call notes path or chat reference (provenance for the ledger)
  artifacts?: any[]; // Artifact links to attach: [{ kind: "pr"|"page"|"deploy"|"doc"|"image"|"url", url, title? }]. Every link must be something a teammate can open in a browser and SEE — a page, mockup, image, PR/commit, deploy, or doc. Never API routes, code file paths, localhost URLs, or anything that renders raw JSON. Most work has no viewable surface (an API change, a refactor, a migration) and a PR is viewable only to the developers on the team: for those, publish a short page (pages createPage) and attach it as kind "page". Never close real work with nothing attached. Always set title, in plain language a teammate recognizes at a glance ("The fix, on GitHub", "Live on production") — never commit hashes, conventional-commit prefixes, raw URLs, or timestamps.
}
export interface ItemsProposeItemArgs {
  title: string; // Imperative, specific title for the proposed work in plain language (max 200 chars) — renders on teammates' home feeds
  source?: string; // Where the discovery came from — what you were working on when you found it
  artifacts?: any[]; // Artifact links to attach: [{ kind: "pr"|"page"|"deploy"|"doc"|"image"|"url", url, title? }]. Every link must be something a teammate can open in a browser and SEE — a page, mockup, image, PR/commit, deploy, or doc. Never API routes, code file paths, localhost URLs, or anything that renders raw JSON. Most work has no viewable surface (an API change, a refactor, a migration) and a PR is viewable only to the developers on the team: for those, publish a short page (pages createPage) and attach it as kind "page". Never close real work with nothing attached. Always set title, in plain language a teammate recognizes at a glance ("The fix, on GitHub", "Live on production") — never commit hashes, conventional-commit prefixes, raw URLs, or timestamps.
}
export interface ItemsOpenItemArgs {
  itemKey: string; // The item key, e.g. "043-rebuild-the-flaky-websocket-reconnect" (find it with listItems)
  source?: string; // Where the approval was decided — chat thread or call reference
  artifacts?: any[]; // Artifact links to attach: [{ kind: "pr"|"page"|"deploy"|"doc"|"image"|"url", url, title? }]. Every link must be something a teammate can open in a browser and SEE — a page, mockup, image, PR/commit, deploy, or doc. Never API routes, code file paths, localhost URLs, or anything that renders raw JSON. Most work has no viewable surface (an API change, a refactor, a migration) and a PR is viewable only to the developers on the team: for those, publish a short page (pages createPage) and attach it as kind "page". Never close real work with nothing attached. Always set title, in plain language a teammate recognizes at a glance ("The fix, on GitHub", "Live on production") — never commit hashes, conventional-commit prefixes, raw URLs, or timestamps.
}
export interface ItemsCloseItemArgs {
  itemKey: string; // The item key of the finished work (find it with listItems)
  closeout?: string; // How the work actually landed — 2 to 4 sentences: what changed, any caveat, what to watch. It supersedes the progress notes, so it must stand alone, and shorter is better — a closeout is a record, not an essay. Plain language a teammate can read; it belongs here on the item, never on the home card.
  source?: string; // Optional provenance note if the item is missing one
  artifacts?: any[]; // Artifact links to attach: [{ kind: "pr"|"page"|"deploy"|"doc"|"image"|"url", url, title? }]. Every link must be something a teammate can open in a browser and SEE — a page, mockup, image, PR/commit, deploy, or doc. Never API routes, code file paths, localhost URLs, or anything that renders raw JSON. Most work has no viewable surface (an API change, a refactor, a migration) and a PR is viewable only to the developers on the team: for those, publish a short page (pages createPage) and attach it as kind "page". Never close real work with nothing attached. Always set title, in plain language a teammate recognizes at a glance ("The fix, on GitHub", "Live on production") — never commit hashes, conventional-commit prefixes, raw URLs, or timestamps.
}
export interface ItemsNoteItemArgs {
  itemKey: string; // The item key to note (find it with listItems)
  note: string; // The progress note — what advanced, in 1 to 3 plain-language sentences. Notes are superseded by the closeout when the item closes, so record the news, not the journey. Not a status change.
  artifacts?: any[]; // Artifact links to attach: [{ kind: "pr"|"page"|"deploy"|"doc"|"image"|"url", url, title? }]. Every link must be something a teammate can open in a browser and SEE — a page, mockup, image, PR/commit, deploy, or doc. Never API routes, code file paths, localhost URLs, or anything that renders raw JSON. Most work has no viewable surface (an API change, a refactor, a migration) and a PR is viewable only to the developers on the team: for those, publish a short page (pages createPage) and attach it as kind "page". Never close real work with nothing attached. Always set title, in plain language a teammate recognizes at a glance ("The fix, on GitHub", "Live on production") — never commit hashes, conventional-commit prefixes, raw URLs, or timestamps.
}
export interface ItemsListItemsArgs {
  status?: string; // Filter to one status: "open", "proposed", or "done". An explicit status is unwindowed — "done" returns the full history
  doneWithinDays?: number; // When listing without a status: how many days of done items to include (default 7; 0 = no window). Live items are always included
}
export interface ItemsGetItemArgs {
  itemKey: string; // The item key to read, e.g. "042-auth-retry" (find it with listItems)
  allNotes?: boolean; // On a done item the closeout supersedes the progress notes, so they are left out by default (progressNotesElided says how many). Pass true to read the full note history
}
export interface ItemsRequestDecisionArgs {
  itemKey: string; // The open item the question is about (find it with listItems)
  question: string; // The one thing you need decided, as a question in plain language (max 140 chars, single line) — e.g. "Cap auth retries at 3, or keep trying until the network returns?". A teammate reads this as one row on their phone, so no context paragraph and no instructions: put those in a noteItem on the same item.
}
export interface ItemsPublishUpdateArgs {
  headline?: string; // Optional one-line lead above the slots (≤80 chars), e.g. "Meetings are a real feature now". Skip it if the shipped lines speak for themselves. On a card with a picture this is the caption under it, so make it the takeaway.
  shipped?: any[]; // What landed this burst — [{ text, itemKey?, heroPageUrl? }], at most 3 lines, one OUTCOME each (≤140 chars, single line). Fold related changes into one line; move the "how" to the item closeout. Set itemKey to deep-link the line to its ledger item. Set heroPageUrl to a Mirra page URL (already published and attached) to make that outcome the card's picture — the FIRST line with one becomes the card face, so order your lines by what matters most.
  next?: any[]; // What you are working on now — [{ text, itemKey?, heroPageUrl? }], at most 2 lines, one thing each (≤140 chars).
  needsYou?: any[]; // What you need from the team — a question or decision — [{ text, itemKey?, heroPageUrl? }], at most 2 lines (≤140 chars). Renders on an attention block so teammates see the ask on the scroll-past, and stays on the card face even when the card leads with a picture. A picture works well here: two options as one page beats describing both.
  defaultBody?: string; // DEPRECATED legacy prose body (plain text; capped at 60 words / 5 lines for one more release, then rejected). Prefer shipped/next/needsYou. When slots are supplied this is derived automatically and any value here is ignored.
  recipientBodies?: any[]; // Per-teammate prose versions: [{ userId? , username?, body }] — give userId or username of an active space member. Each recipient sees their prose version instead of the slots; nobody else ever sees it. On a revision these are the one part of a card that is NOT replaced wholesale: pass any and they replace the set, omit them and the existing ones stay. Revising without them used to delete them silently.
  itemKeys?: any[]; // Extra item keys this update covers beyond those named on lines (rendered as chips). Must exist in this space. Line itemKeys are added automatically.
  artifacts?: any[]; // Artifact links to attach: [{ kind: "pr"|"page"|"deploy"|"doc"|"image"|"url", url, title? }]. Every link must be something a teammate can open in a browser and SEE — a page, mockup, image, PR/commit, deploy, or doc. Never API routes, code file paths, localhost URLs, or anything that renders raw JSON. Most work has no viewable surface (an API change, a refactor, a migration) and a PR is viewable only to the developers on the team: for those, publish a short page (pages createPage) and attach it as kind "page". Never close real work with nothing attached. Always set title, in plain language a teammate recognizes at a glance ("The fix, on GitHub", "Live on production") — never commit hashes, conventional-commit prefixes, raw URLs, or timestamps.
}

