// Work Items Response Types
export interface WorkItem {
  itemKey: string; // Server-assigned key, e.g. "042-auth-retry"
  status: any; // Ledger status
  title: string; // Item title
  ownerUserId?: string; // Owner user id (absent when unowned)
  ownerName?: string; // Owner display name
  source?: string; // Provenance — where this work was decided/found
  via: string; // How the last write happened: 'op' (agent), 'call', or 'git'
  artifacts: any; // Attached artifact refs [{ kind, url, title? }]
  notes: any; // Progress notes + closeout, oldest first [{ at, text, closing, actorName?, via }]. The note with closing:true is the closeout.
  resolution?: any; // How a human decided this when it was proposed. 'declined' on a done item means the team said no — that work was NOT shipped. Absent on items nobody decided, including anything a git push flipped.
  decidedByName?: string; // Who decided, by display name (present with resolution)
  decidedAt?: string; // ISO timestamp of the decision (present with resolution)
  needsDecision?: any; // The question standing on this item, if any: { questionId, question, askedByUserId, askedByName?, askedAt }. askedByUserId is you when the question is yours.
  lastResolvedQuestionId?: string; // The last question an answer closed. Set with no needsDecision means somebody replied — getItem returns the reply in discussion.
  doneAt?: string; // ISO timestamp when closed (done items only)
  createdAt: string; // ISO creation timestamp
  updatedAt: string; // ISO last-write timestamp
}

